sp_widget.client_script:
api.controller = function() {
  var c = this;

  // This ensures c.data is available in the HTML template
  c.data = c.data || {};

  var spUtil = angular.element(document.body).injector().get('spUtil');
  spUtil.addInfoMessage("Welcome back! Your secure Launchpad terminal workspace is fully synchronized.");
};

sp_widget.css:
/*
===============================================================================
LAUNCHPAD HERO WIDGET — SPAR Futuristic edition
Paste into the widget's CSS field (or append to the theme's CSS field)
Uses the same $brand-primary / $brand-success / $glow-primary / $glow-success
tokens as the rest of the theme, so it stays in sync if the palette changes.
===============================================================================
*/

/* Container — soft glass, gradient top edge like the rest of the panels */
.launchpad-hero-container {
  position: relative;
  padding: 60px 40px;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(6px);
  border: 1px solid #E2E8F0;
  border-radius: 16px;
  overflow: hidden;
  margin-top: 24px;
  box-shadow: 0 4px 20px -2px rgba(15, 23, 42, 0.06);
  transition: box-shadow 300ms ease;
}
.launchpad-hero-container::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, $brand-primary 0%, $brand-success 100%);
  background-size: 200% 100%;
  animation: gradientShift 5s ease infinite;
}
.launchpad-hero-container:hover {
  box-shadow: 0 12px 32px -4px rgba(227, 6, 19, 0.14);
}

/* Animated accent blobs — dual-tone red + green drift, replacing the single blue blob */
.accent-blob {
  position: absolute;
  width: 320px;
  height: 320px;
  background: radial-gradient(circle, $glow-primary 0%, transparent 70%);
  border-radius: 50%;
  top: -80px;
  right: -60px;
  opacity: 0.55;
  animation: blob-drift 8s ease-in-out infinite;
  pointer-events: none;
}
.accent-blob--secondary {
  position: absolute;
  width: 260px;
  height: 260px;
  background: radial-gradient(circle, $glow-success 0%, transparent 70%);
  border-radius: 50%;
  bottom: -70px;
  left: -50px;
  opacity: 0.5;
  animation: blob-drift 10s ease-in-out infinite reverse;
  pointer-events: none;
}

/* Greeting sub — bold SPAR red, slides in from left */
.greeting-sub {
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: $brand-primary !important;
  margin-bottom: 8px;
  opacity: 0;
  animation: slide-in-left 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) 0.1s forwards;
}

/* Main heading — bold, near-black with a subtle red-to-green gradient sweep on the accent word (wrap the key word in <span class="greeting-accent">) */
.greeting-main {
  font-size: 2.5rem;
  font-weight: 800;
  color: #0F172A !important;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
  opacity: 0;
  animation: slide-in-left 0.7s cubic-bezier(0.34, 1.56, 0.64, 1) 0.25s forwards;
}
.greeting-main .greeting-accent {
  background: linear-gradient(90deg, $brand-primary 0%, $brand-success 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent !important;
}

/* Lead paragraph — fades up last */
.greeting-lead {
  font-size: 1rem;
  line-height: 1.6;
  color: #334155 !important;
  opacity: 0;
  animation: fade-up 0.7s cubic-bezier(0.4, 0, 0.2, 1) 0.45s forwards;
}

/* Optional CTA row under the lead — bold gradient pill button + glow, same
   language as the "Request Access" button elsewhere in the theme */
.greeting-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 24px;
  padding: 12px 28px;
  border-radius: 999px;
  border: none;
  background: linear-gradient(135deg, $gradient-primary-start 0%, $gradient-primary-end 100%);
  color: #ffffff;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  font-size: 0.85rem;
  box-shadow: 0 6px 18px $glow-primary;
  opacity: 0;
  cursor: pointer;
  transition: transform 250ms cubic-bezier(0.34,1.56,0.64,1), box-shadow 250ms ease;
  animation: fade-up 0.7s cubic-bezier(0.4, 0, 0.2, 1) 0.6s forwards;
}
.greeting-cta:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 26px $glow-primary;
}

/* ── Keyframes ── */
@keyframes slide-in-left {
  from { opacity: 0; transform: translateX(-28px); }
  to   { opacity: 1; transform: translateX(0); }
}
@keyframes fade-up {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes blob-drift {
  0%, 100% { transform: translate(0, 0) scale(1); }
  33%      { transform: translate(-20px, 15px) scale(1.05); }
  66%      { transform: translate(10px, -20px) scale(0.97); }
}
@keyframes gradientShift {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

sp_widget.script:
(function() {
  var userGR = new GlideRecord('sys_user');
  if (userGR.get(gs.getUserID())) {
    data.firstName = userGR.getValue('first_name') || 'Explorer';
    data.lastName = userGR.getValue('last_name') || '';
  } else {
    data.firstName = 'Explorer';
    data.lastName = '';
  }
})();
